By Theorem \ref{theorem: generalized prekopa-leindler inequality},
\begin{equation*}
\begin{split}
g(x)&=\hspace{-0.1cm}\int_{\mathbb{R}^m}H_s(y)dy=\hspace{-0.1cm}\int_{\mathbb{R}^m}h_s(y)I_{K(x)}(y)dy\ge \hspace{-0.1cm}\left[(1\hspace{-0.1cm}-\hspace{-0.1cm}\lambda)\hspace{-0.1cm}\left(\int_{\mathbb{R}^n}\hspace{-0.2cm}G_1(y)dy\right)^\gamma\hspace{-0.2cm}+\hspace{-0.1cm}\lambda\left(\int_{\mathbb{R}^n}\hspace{-0.2cm}G_2(y)dy\right)^\gamma\right]^{1/\gamma}\\
&=\left[(1-\lambda)\left(\int_{\mathbb{R}^n}f(x_1,y_1)I_{K(x_1)}(y_1)dy_1\right)^\gamma+\lambda\left(\int_{\mathbb{R}^n}f(x_2,y_2)I_{K(x_2)}(y_2)dy_2\right)^\gamma\right]^{1/\gamma}\\
&=\left[(1-\lambda)g(x_1)^\gamma+\lambda g(x_2)^\gamma\right]^{1/\gamma},
\end{split}
\end{equation*}
where $\gamma=s/(1+ms)$. Namely, the marginal function $g(x)$ is $\gamma$-concave.

We now set $K$ large enough so that $1/c<K$. Then
\begin{equation*}
G(x)\le
\begin{cases}
G(0)(1+\gamma cx)^\frac{1}{\gamma}, & \mbox{if}\ x\le 1/c,\\
1, & \mbox{if}\ x> 1/c.
\end{cases}
\end{equation*}
So
\begin{equation*}
\begin{split}
K&=\int_{-K}^KG(x)dx\\
&\le \int_{-K}^{1/c}G(0)(1+\gamma cx)^\frac{1}{\gamma}dx+\int_{1/c}^K1dx\\
&=\frac{G(0)}{c(\gamma+1)}[(1+\gamma)^{\frac{1}{\gamma}+1}-(1-\gamma cK)^{\frac{1}{\gamma}+1}]+K-\frac{1}{c}\\
&\le\frac{G(0)(1+\gamma)^{\frac{1}{\gamma}}}{c}+K-\frac{1}{c},
\end{split}
\end{equation*}
which implies that $G(0)\ge (1+\gamma)^{-1/\gamma}$ as claimed.

(c) The intuition behind the proof is to choose a baseline $s$-concave function $h$ which is at the ``boundary" between the family of $s$-concave function and that of the non $s$-concave function. We show that $h$ satisfies the equation
\begin{equation} T_n(h)T_{n+2}(h)=T_{n+1}^2(h).
\end{equation}
Then by the facts that $h$ is at the ``boundary" and $g$ is any $s$-concave function, we have
\begin{equation} T_{n+1}(h)\le T_{n+1}(g).
\end{equation}
The conclusion follows from \eqref{equ: equality for special function} and \eqref{equ: comparison}, and from our choice of $h$ such that $T_n(h)=T_n(g)$ and $T_{n+2}(h)=T_{n+2}(g)$, by adjusting the slope and intercept of the linear function.

Formally, let $h(t)=\beta(1+\gamma t)^{1/s}$ be the above-mentioned baseline $s$-concave function ($\beta,\gamma>0$) such that
\begin{equation*}
M_n(h)=M_n(g)\ \ \ \ \mbox{and}\ \ \ \ M_{n+2}(h)=M_{n+2}(g)
\end{equation*}
(This holds because there are two parameters $\beta,\gamma$ and two equations). That means
\begin{equation*}
\int_0^\infty t^n(h(t)-g(t))dt=0\ \ \ \ \mbox{and}\ \ \ \ \int_0^\infty t^{n+2}(h(t)-g(t))dt=0.
\end{equation*}
Then it follows that the graph of $h$ must intersect the graph of $g$ at least twice. Since $g$ is $s$-concave, which implies the uni-modality, the graphs of $h$ and $g$ intersect exactly at two points $0\le a<b$. Moreover, $h\le g$ in the interval $[a,b]$ and $h\ge g$ outside the interval. That is to say, $(t-a)(t-b)$ has the same sign as $h-g$. Thus
\begin{equation*}
\int_0^{\infty} (t-a)(t-b)t^n(h(t)-g(t))dt\ge 0.
\end{equation*}
Namely,
\begin{equation*}
0=\int_0^{\infty}t^{n+2}(h(t)-g(t))dt+ab\int_0^{\infty}t^n(h(t)-g(t))dt\ge (a+b)\int_0^\infty t^{n+1}(h(t)-g(t))dt.
\end{equation*}
This implies that
\begin{equation*}
M_{n+1}(h)=\int_0^{\infty}t^{n+1}h(t)dt\le\int_0^\infty t^{n+1}g(t)dt=M_{n+1}(g).
\end{equation*}
Since
\begin{equation*} M_n(h)=\int_0^\infty t^n\beta(1+\gamma t)^{1/s}dt=B(-1/s-n-1,n+1)\frac{\beta}{\gamma^{n+1}}
\end{equation*}
for $s>-1/(n+1)$, we have
\begin{equation*}
\begin{split}
\frac{M_n(g)}{B(-1/s-n-1,n+1)}\frac{M_{n+2}(g)}{B(-1/s-n-3,n+3)}&=\frac{M_n(h)}{B(-1/s-n-1,n+1)}\frac{M_{n+2}(h)}{B(-1/s-n-3,n+3)}\\
&=\frac{\beta}{\gamma^{n+1}}\cdot \frac{\beta}{\gamma^{n+3}}\\
&=\left(\frac{M_{n+1}(h)}{B(-1/s-n-2,n+2)}\right)^2\\
&\le \left(\frac{M_{n+1}(g)}{B(-1/s-n-2,n+2)}\right)^2,
\end{split}
\end{equation*}
as desired.

