\Pr((-H_u)\cap(-H_v)\cap H')\le K\Pr(H_u\cap H_v\cap (-H'))\le \frac{\delta}{4(1+\gamma)^{1/\gamma}m_1}.
\end{equation*}
On the other hand, by Lemma \ref{lemma: probability of halfspace}, $\Pr(H')\ge (1+\gamma)^{-1/\gamma}$ with $\gamma=s/(1+ns)$. Thus
\begin{equation*}
\Pr((-H_u)\cap (-H_v)|H')=\frac{\Pr((-H_u)\cap(-H_v)\cap(H'))}{\Pr(H')}\le \frac{\delta}{4m_1}.
\end{equation*}

That is to say, each point in $S$ has probability at most $\delta/(4m_1)$ of being in $(-H_u)\cap(-H_v)$. So by the union bound, with probability at least $1-\delta/4$, none of points in $S$ is in $(-H_u)\cap(-H_v)$. Therefore, Step 6 in Algorithm \ref{algorithm: intersections of halfspaces} is able to find $h_{xor}$ that is consistent with all the instances in $S$. Then by the VC argument, we have
\begin{equation*}
\Pr(h_{xor(x)}\not= c(x)|x\in H')\le \frac{\epsilon}{2},
\end{equation*}
with probability at least $1-\delta/4$.

In summary, we have
\begin{equation*}
\begin{split}
\textup{\textsf{err}}(h)&=\Pr(-H')\Pr(H_u\cap H_v|-H')+\Pr(H')\Pr(h_{xor}(x)\not=c(x)|x\in H')\\
&\le \frac{\epsilon}{2}+\frac{\epsilon}{2}=\epsilon,
\end{split}
\end{equation*}
with failure probability at most $\delta/4+\delta/4+\delta=\delta$ by the union bound. Therefore, the proof is completed.
